#include <iostream>
#include <memory>
#include <vector>
#include <utility>
#include <string>

int solve(int a, int b) { auto source = std::make_unique<int>(a); auto destination = std::move(source); if (source) return -9999; source = std::make_unique<int>(b); return *source + *destination; }
